import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    static int n, m, K;
    static int[] head, nxt, to, wt, dist, queue;

    // BFS from 1 over edges of weight <= lim, never expanding past depth K.
    static boolean ok(int lim) {
        Arrays.fill(dist, -1);
        int qh = 0, qt = 0;
        queue[qt++] = 1;
        dist[1] = 0;
        while (qh < qt) {
            int u = queue[qh++];
            if (dist[u] >= K) continue;
            for (int e = head[u]; e >= 0; e = nxt[e]) {
                if (wt[e] <= lim && dist[to[e]] < 0) {
                    dist[to[e]] = dist[u] + 1;
                    queue[qt++] = to[e];
                }
            }
        }
        return dist[n] >= 0 && dist[n] <= K;
    }

    public static void main(String[] args) throws IOException {
        n = (int) nextLong(); m = (int) nextLong(); K = (int) nextLong();
        head = new int[n + 1];
        Arrays.fill(head, -1);
        nxt = new int[2 * m]; to = new int[2 * m]; wt = new int[2 * m];
        int[] ws = new int[m];
        for (int i = 0; i < m; i++) {
            int a = (int) nextLong(), b = (int) nextLong(), w = (int) nextLong();
            ws[i] = w;
            to[2 * i] = b; wt[2 * i] = w; nxt[2 * i] = head[a]; head[a] = 2 * i;
            to[2 * i + 1] = a; wt[2 * i + 1] = w; nxt[2 * i + 1] = head[b]; head[b] = 2 * i + 1;
        }
        Arrays.sort(ws);
        int u = 0;
        for (int i = 0; i < m; i++) if (i == 0 || ws[i] != ws[i - 1]) ws[u++] = ws[i];
        dist = new int[n + 1];
        queue = new int[n + 1];
        // Binary search the smallest distinct weight that is feasible.
        int lo = 0, hi = u - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(ws[mid])) hi = mid; else lo = mid + 1;
        }
        System.out.println(ws[lo]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n, m, k := int(readInt()), int(readInt()), int(readInt())
	head := make([]int32, n+1)
	for i := range head {
		head[i] = -1
	}
	nxt, to, wt := make([]int32, 2*m), make([]int32, 2*m), make([]int32, 2*m)
	ws := make([]int32, m)
	for i := 0; i < m; i++ {
		a, b, w := int32(readInt()), int32(readInt()), int32(readInt())
		ws[i] = w
		to[2*i], wt[2*i], nxt[2*i], head[a] = b, w, head[a], int32(2*i)
		to[2*i+1], wt[2*i+1], nxt[2*i+1], head[b] = a, w, head[b], int32(2*i+1)
	}
	slices.Sort(ws)
	ws = slices.Compact(ws)
	dist := make([]int32, n+1)
	queue := make([]int32, 0, n+1)
	// BFS from 1 over edges of weight <= lim, never expanding past depth k.
	ok := func(lim int32) bool {
		for i := range dist {
			dist[i] = -1
		}
		queue = append(queue[:0], 1)
		dist[1] = 0
		for i := 0; i < len(queue); i++ {
			u := queue[i]
			if int(dist[u]) >= k {
				continue
			}
			for e := head[u]; e >= 0; e = nxt[e] {
				if wt[e] <= lim && dist[to[e]] < 0 {
					dist[to[e]] = dist[u] + 1
					queue = append(queue, to[e])
				}
			}
		}
		return dist[n] >= 0 && int(dist[n]) <= k
	}
	// Binary search the smallest distinct weight that is feasible.
	lo, hi := 0, len(ws)-1
	for lo < hi {
		mid := (lo + hi) / 2
		if ok(ws[mid]) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(ws[lo])
}
